CREATE PROCEDURE [sync].[gsp_ServerSelectUpdateConflicts_tblTransactionAliases]
@TransactionAliasGuid uniqueidentifier
AS
BEGIN
    -- This command is used if @sync_row_count returns
    -- 0 when changes are applied to the server.
    --
    SELECT [dbo].[tblTransactionAliases].[AliasName],[dbo].[tblTransactionAliases].[MeterCloseout],[dbo].[tblTransactionAliases].[BulkShipment],[dbo].[tblTransactionAliases].[DistributedImpact],[dbo].[tblTransactionAliases].[MultipleLineItems],[dbo].[tblTransactionAliases].[LimitSelectionsBasedOnHierarchy],[dbo].[tblTransactionAliases].[LineItemEditControl],[dbo].[tblTransactionAliases].[MultipleWeightReadings],[dbo].[tblTransactionAliases].[WeightReadingEditControl],[dbo].[tblTransactionAliases].[AssociatedReport],[dbo].[tblTransactionAliases].[AssociatedPreloadReport],[dbo].[tblTransactionAliases].[DestinationEquipmentTypes1],[dbo].[tblTransactionAliases].[DestinationEquipmentTypes2],[dbo].[tblTransactionAliases].[DestinationEquipmentTypes3],[dbo].[tblTransactionAliases].[SourceEquipmentTypes1],[dbo].[tblTransactionAliases].[SourceEquipmentTypes2],[dbo].[tblTransactionAliases].[SourceEquipmentTypes3],[dbo].[tblTransactionAliases].[CreatedDate],[dbo].[tblTransactionAliases].[CreatedBy],[dbo].[tblTransactionAliases].[UpdatedDate],[dbo].[tblTransactionAliases].[UpdatedBy],[dbo].[tblTransactionAliases].[ShowCompanyName],[dbo].[tblTransactionAliases].[AggregateAssocTrans],[dbo].[tblTransactionAliases].[EnableTotalQuantityExceededWarning],[dbo].[tblTransactionAliases].[EnableQuantityToleranceExceededWarning],[dbo].[tblTransactionAliases].[EnableTotalValueExceededWarning],[dbo].[tblTransactionAliases].[EnableValueToleranceExceededWarning],[dbo].[tblTransactionAliases].[LevelUnitIndex],[dbo].[tblTransactionAliases].[TemperatureUnitIndex],[dbo].[tblTransactionAliases].[DensityUnitIndex],[dbo].[tblTransactionAliases].[PressureUnitIndex],[dbo].[tblTransactionAliases].[FlowUnitIndex],[dbo].[tblTransactionAliases].[VolumeUnitIndex],[dbo].[tblTransactionAliases].[MassUnitIndex],[dbo].[tblTransactionAliases].[AdditiveVolumeUnitIndex],[dbo].[tblTransactionAliases].[AdditiveProfileCycleAmountUnitIndex],[dbo].[tblTransactionAliases].[AdditiveProfileRateUnitIndex],[dbo].[tblTransactionAliases].[LevelDecimalPlaces],[dbo].[tblTransactionAliases].[TemperatureDecimalPlaces],[dbo].[tblTransactionAliases].[DensityDecimalPlaces],[dbo].[tblTransactionAliases].[PressureDecimalPlaces],[dbo].[tblTransactionAliases].[FlowDecimalPlaces],[dbo].[tblTransactionAliases].[VolumeDecimalPlaces],[dbo].[tblTransactionAliases].[MassDecimalPlaces],[dbo].[tblTransactionAliases].[AdditiveVolumeDecimalPlaces],[dbo].[tblTransactionAliases].[UseComboBoxControls],[dbo].[tblTransactionAliases].[MultipleTransportLineItems],[dbo].[tblTransactionAliases].[TransactionAliasGuid],[dbo].[tblTransactionAliases].[SiteGuid],[dbo].[tblTransactionAliases].[LookupTransTypeIndex],[dbo].[tblTransactionAliases].[LookupDefaultStatusIndex],[dbo].[tblTransactionAliases].[AssociatedTransactionAliasGuid],[dbo].[tblTransactionAliases].[IncludeInDispatch],[dbo].[tblTransactionAliases].[_MasterRecordGuid],[dbo].[tblTransactionAliases].[EnableAutoCompleteControls],[dbo].[tblTransactionAliases].[PermitNonReferenceData],[dbo].[tblTransactionAliases].[UseTransactionDetailWithLayout],[dbo].[tblTransactionAliases].[DefaultMeterToEquipmentID],[dbo].[tblTransactionAliases].[LimitSourceEquipmentByProduct],[dbo].[tblTransactionAliases].[RememberMeterEndForMeterID],[dbo].[tblTransactionAliases].[PopulateCompaniesFromEquipment],[dbo].[tblTransactionAliases].[PopulateGrossVolumeFromMeterValues],[dbo].[tblTransactionAliases].[UseMeterAndCompressionFactorFromMeter], CT.UpdatedContext, CT.UpdatedRowVersion AS '_RowVersion'
        FROM [dbo].[tblTransactionAliases]
            INNER JOIN [track].[tblTransactionAliases] CT
                ON CT.PK_TransactionAliasGuid = [dbo].[tblTransactionAliases].[TransactionAliasGuid]
        WHERE CT.PK_TransactionAliasGuid = @TransactionAliasGuid
    ORDER BY CT.UpdatedRowVersion ASC
END
